insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('a3505889-6558-434c-adce-3b51d9d486b4', 'b53e4a85-5a16-4d3f-b4b9-7ddbecaca244', $$f(x) = 4^(x+1) − 3 en g(x) = 8 + ²log(4(x + 1½)); A op f en B op g met y-coördinaat 13; figuur$$,
   $$wiskunde-b-havo-2019-ii-een-logaritmische-en-een-exponentiele-functie-context1.png$$,
   $$De functies f en g worden gegeven door:
f(x) = 4^(x+1) − 3 en g(x) = 8 + ²log(4(x + 1½))
Op de grafiek van f ligt een punt met y-coördinaat 13. Dat is het punt A.
Op de grafiek van g ligt ook een punt met y-coördinaat 13. Dat is het punt B.
Zie de figuur, waarin het lijnstuk AB vet weergegeven is.
figuur: de grafieken van f en g met het lijnstuk AB op hoogte 13$$, 'inline'),
  ('eb2a8c4c-c8d5-4081-86a7-e9435ffa2ce7', 'b53e4a85-5a16-4d3f-b4b9-7ddbecaca244', $$grafiek van g ontstaat uit y = ²log(x) door een horizontale en een verticale translatie; vorm g(x) = ²log(x + a) + b$$,
   $$wiskunde-b-havo-2019-ii-een-logaritmische-en-een-exponentiele-functie-context2.png$$,
   $$De grafiek van g ontstaat uit de grafiek van de standaardfunctie y = ²log(x) door een horizontale en een verticale translatie.
Door het functievoorschrift van g te herleiden tot de vorm g(x) = ²log(x + a) + b kun je op exacte wijze berekenen om welke horizontale en verticale translatie het gaat.$$, 'inline'),
  ('f07c43e9-4444-4e96-b57d-c55b06913af9', '8ad98cf1-2a68-409f-a226-83e377eee841', $$driehoek ABC met AB = 11, BC = 8, AC = 5; CD loodrecht op AB; DE evenwijdig aan BC; figuur$$,
   $$wiskunde-b-havo-2019-ii-hoe-lang-is-de-context1.png$$,
   $$Gegeven is driehoek ABC met AB = 11, BC = 8 en AC = 5.
Het punt D ligt op zijde AB, zo dat lijnstuk CD loodrecht op zijde AB staat.
Punt E ligt op zijde AC, zo dat lijnstuk DE evenwijdig is met zijde BC.
Zie de figuur.
figuur: driehoek ABC met hoogtelijn CD en lijnstuk DE evenwijdig aan BC$$, 'inline'),
  ('9e813286-0a0b-448d-b256-61e0fe8f04af', '73954cc5-023b-4265-863b-4b28a3429b2e', $$viscositeit V van suikerwater: V = (1 + 0,5C)/(1 − C)⁴; C concentratie suiker$$,
   $$wiskunde-b-havo-2019-ii-viscositeit-context1.png$$,
   $$Er wordt veel onderzoek gedaan naar de viscositeit van vloeistoffen.
De viscositeit van een vloeistof is een getal dat aangeeft hoe stroperig die vloeistof is: hoe groter de viscositeit, hoe stroperiger die vloeistof.
Suiker kun je in water oplossen. De concentratie suiker bepaalt de viscositeit van de vloeistof die zo ontstaat. Aan het begin van de twintigste eeuw is het volgende theoretische verband afgeleid tussen de concentratie suiker en de viscositeit:
V = (1 + 0,5C)/(1 − C)⁴
Hierin is V de viscositeit en C de concentratie suiker.
Hierbij wordt met een concentratie van bijvoorbeeld C = 0,3 bedoeld dat het volume van de suiker 30% van het totale volume van de vloeistof is.$$, 'inline'),
  ('0527ccee-e8ce-4220-b339-d82a85109985', '73954cc5-023b-4265-863b-4b28a3429b2e', $$Tessa: concentratie 0,17; na toevoeging van suiker is de viscositeit verdubbeld$$,
   $$wiskunde-b-havo-2019-ii-viscositeit-context2.png$$,
   $$Tessa heeft een glas water gekregen waarin suiker is opgelost. De concentratie suiker in het water is 0,17. Vervolgens voegt ze nog meer suiker toe. Na deze toevoeging blijkt de viscositeit verdubbeld te zijn.$$, 'inline'),
  ('3b7f5214-2346-48c3-a014-7339528e4bf1', '73954cc5-023b-4265-863b-4b28a3429b2e', $$lineaire benadering Vlin = a · C + b met a = V′(0) en b = V(0); V′(0) benaderen met differentiequotiënt ΔV/ΔC$$,
   $$wiskunde-b-havo-2019-ii-viscositeit-context3.png$$,
   $$Ongeveer gelijktijdig met de vondst van de formule voor V stelde de scheikundige Emil Hatschek een lineaire formule op voor het verband tussen de viscositeit en de concentratie suiker:
Vlin = a · C + b
Hierin is Vlin een benadering van V.
Voor dit lineaire verband geldt: a = V′(0) en b = V(0).
De waarde van V′(0) kan benaderd worden door het differentiequotiënt ΔV/ΔC op een heel klein interval.$$, 'inline'),
  ('910c2553-8f51-4f9e-a3d1-0253341748ff', '5236e4b7-09d0-4acf-89e8-26c7f2244e93', $$f(x) = −(2x − 3)³ + 3x² − 6x + 4; f′(x) = −24x² + 78x − 60$$,
   $$wiskunde-b-havo-2019-ii-twee-toppen-en-twee-evenwijdige-lijnen-context1.png$$,
   $$De functie f wordt gegeven door f(x) = −(2x − 3)³ + 3x² − 6x + 4.
Voor de afgeleide functie van f geldt: f′(x) = −24x² + 78x − 60.$$, 'inline'),
  ('e9a6c79b-9342-495e-9710-2ec8e1299ad4', '5236e4b7-09d0-4acf-89e8-26c7f2244e93', $$toppen A en B, lijn k door A en B; P(1, 2) op f; l // k door P; K, M en L, N snijpunten met de assen; driehoek OKM gelijkvormig met OLN; KM is z keer zo lang als LN; figuur$$,
   $$wiskunde-b-havo-2019-ii-twee-toppen-en-twee-evenwijdige-lijnen-context2.png$$,
   $$De grafiek van f heeft twee toppen. Dit zijn de punten A en B. De lijn k is de lijn door A en B.
Het punt P(1, 2) ligt op de grafiek van f.
De lijn l is evenwijdig aan lijn k en gaat door P.
Lijn k snijdt de x-as in punt K en de y-as in punt M.
Lijn l snijdt de x-as in punt L en de y-as in punt N.
Vanwege de evenwijdigheid van lijn k en lijn l is driehoek OKM gelijkvormig met driehoek OLN.
Zie de figuur.
figuur: de grafiek van f met de toppen A en B, de evenwijdige lijnen k en l en de driehoeken OKM en OLN
Lijnstuk KM is z keer zo lang als lijnstuk LN.$$, 'inline'),
  ('d806108d-240a-43cd-833b-b925efb2a2c4', '3fdffc49-6b25-4e61-b71d-86797e45965a', $$fietsen tegen de wind: Pvlak = 0,00386 · v · (v + vwind)²; Pvlak in W, v en vwind in km/uur$$,
   $$wiskunde-b-havo-2019-ii-nk-tegenwindfietsen-context1.png$$,
   $$Om tegen de wind in te fietsen, moet je flink hard trappen.
In deze opgave gaan we ervan uit dat de snelheid van een fietser constant is en dat de snelheid van de tegenwind constant is.
Als je op een vlakke weg tegen de wind in fietst, moet je vermogen leveren. Je kunt dit vermogen als volgt berekenen:
Pvlak = 0,00386 · v · (v + vwind)²
Hierin is Pvlak het vermogen in watt (W), v de snelheid van de fietser in km/uur en vwind de snelheid van de tegenwind in km/uur.
Zowel v als vwind zijn positief.$$, 'inline'),
  ('e899ef9d-dc1e-4a6f-94e2-08864f89f414', '3fdffc49-6b25-4e61-b71d-86797e45965a', $$NK Tegenwindfietsen over 8,5 km; foto 1; 2016: Sweere in 22 min 30 s bij tegenwind 80 km/uur; tegenwind 5% groter bij dezelfde snelheid$$,
   $$wiskunde-b-havo-2019-ii-nk-tegenwindfietsen-context2.png$$,
   $$Elk jaar wordt - als het hard genoeg waait - het NK (Nederlands Kampioenschap) Tegenwindfietsen georganiseerd. Hierbij fietsen de deelnemers 8,5 km tegen de wind in.
foto 1: een deelnemer aan het NK Tegenwindfietsen
In 2016 werd het NK Tegenwindfietsen gewonnen door Teun Sweere in een tijd van 22 minuten en 30 seconden bij een tegenwind met een snelheid van 80 km/uur.
Stel dat Sweere bij een toekomstige deelname aan het NK Tegenwindfietsen een tegenwind heeft met een snelheid die 5% groter is dan in 2016, maar dat hij met dezelfde snelheid wil fietsen als in 2016. Hij zal dan een groter vermogen moeten leveren dan tijdens de wedstrijd in 2016.$$, 'inline'),
  ('a19ad49d-cdd4-40c9-b48f-12bac85f9d5c', '3fdffc49-6b25-4e61-b71d-86797e45965a', $$bergop fietsen zonder wind; foto 2; Pbergop = 0,0273 · m · h · v; m massa in kg, h hellingspercentage, v in km/uur$$,
   $$wiskunde-b-havo-2019-ii-nk-tegenwindfietsen-context3.png$$,
   $$Wanneer je bergop fietst, moet je ook flink wat vermogen leveren. We gaan er in de rest van de opgave vanuit dat er bij bergop fietsen geen wind is. Ook nemen we aan dat de berg overal even steil is.
foto 2: een wielrenner die bergop fietst
Het vermogen dat een fietser moet leveren bij bergop fietsen, kun je dan als volgt berekenen: Pbergop = 0,0273 · m · h · v
Hierin is Pbergop het vermogen in watt (W), m de totale massa van de fietser en zijn fiets in kg, h het hellingspercentage van de weg en v de snelheid van de fietser in km/uur.$$, 'inline'),
  ('f9d8560f-cb6f-49e4-a128-c4440ba45ab6', '3fdffc49-6b25-4e61-b71d-86797e45965a', $$Keutenberg: 1,2 km, hellingspercentage 5,9%; Ibrahim levert 210 W; massa 72 kg$$,
   $$wiskunde-b-havo-2019-ii-nk-tegenwindfietsen-context4.png$$,
   $$In Zuid-Limburg ligt de Keutenberg. De weg naar de top is 1,2 km lang en heeft een hellingspercentage van 5,9%. Ibrahim is een amateurwielrenner. Hij legt de weg naar de top van de Keutenberg af met een vermogen van 210 W. De massa van Ibrahim en zijn fiets is in totaal 72 kg.$$, 'inline'),
  ('68b751da-c773-4316-a968-c1d2c0bfdc77', '3fdffc49-6b25-4e61-b71d-86797e45965a', $$Alpe d'Huez: 13,4 km, hellingspercentage 8,4%; Tom wil 19 km/uur; bij NK met wind 70 km/uur evenveel vermogen; massa 78 kg$$,
   $$wiskunde-b-havo-2019-ii-nk-tegenwindfietsen-context5.png$$,
   $$De Alpe d''Huez is een berg in Frankrijk die zeer bekend is van de Tour de France. De weg naar de top heeft een lengte van 13,4 km en een hellingspercentage van 8,4%.
Tom wil de Alpe d''Huez met zijn racefiets beklimmen. Hij heeft zich als doel gesteld om dat met een snelheid van 19 km/uur te gaan doen.
Als onderdeel van zijn training neemt hij deel aan het NK Tegenwindfietsen, waarbij de wind een snelheid heeft van 70 km/uur.
Hij wil daarbij evenveel vermogen leveren als hij bij de rit op de Alpe d''Huez moet leveren om zijn doel te halen. Tom en zijn racefiets hebben samen een massa van 78 kg.$$, 'inline'),
  ('8180d4f6-59c3-4d64-be74-688a28ba5e52', '3633e3c0-343c-4a6a-9f32-c59bf3f84a87', $$f(x) = 1 + 4√x; l raaklijn aan f in A(4, 9); cirkel c: (x + 2)² + (y + 1)² = 8; figuur 1; l en c raken elkaar$$,
   $$wiskunde-b-havo-2019-ii-een-cirkel-en-functies-met-een-wortel-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 1 + 4√x.
De lijn l is de raaklijn aan de grafiek van f in het punt A(4, 9).
Verder is gegeven de cirkel c met vergelijking (x + 2)² + (y + 1)² = 8.
Zie figuur 1.
figuur 1: de grafiek van f, de raaklijn l in A en de cirkel c
Lijn l en cirkel c raken elkaar.$$, 'inline'),
  ('ef350b04-0c67-4cc2-9859-32040f5b94d9', '3633e3c0-343c-4a6a-9f32-c59bf3f84a87', $$S snijpunt van c met de y-as onder de x-as; g(x) = p√x + q met randpunt S en door A; figuur 2$$,
   $$wiskunde-b-havo-2019-ii-een-cirkel-en-functies-met-een-wortel-context2.png$$,
   $$Cirkel c heeft twee snijpunten met de y-as. Een van die twee punten ligt onder de x-as. Dit is het punt S. Zie figuur 2.
De functie g heeft een functievoorschrift van de vorm g(x) = p√x + q.
De grafiek van g heeft S als randpunt en gaat bovendien door A.
In figuur 2 is ook de grafiek van g weergegeven.
figuur 2: de cirkel c en de grafiek van g door S en A$$, 'inline'),
  ('489ed471-5608-418d-aca7-916c3db1758b', '1f27c094-3af5-4b47-a0d5-9636760ec1cd', $$f(x) = −1 + sin(2x − ⅙π); figuur 1; vier waarden van x in [0, 2π] met f(x) = −½$$,
   $$wiskunde-b-havo-2019-ii-sinusoide-en-lijn-context1.png$$,
   $$De functie f wordt gegeven door f(x) = −1 + sin(2x − ⅙π). De grafiek van f is in figuur 1 weergegeven.
figuur 1: de grafiek van f
Er zijn vier waarden van x in het interval 0 ≤ x ≤ 2π waarvoor geldt f(x) = −½.$$, 'inline'),
  ('9dfd19ad-4f5f-4ac6-81b4-71ddb414a349', '1f27c094-3af5-4b47-a0d5-9636760ec1cd', $$grafiek van f raakt de x-as; A raakpunt met kleinste positieve x; stijgende lijn l door A met hoek 75° met de x-as snijdt de y-as in B; figuur 2$$,
   $$wiskunde-b-havo-2019-ii-sinusoide-en-lijn-context2.png$$,
   $$De grafiek van f raakt de x-as in oneindig veel punten. Van deze raakpunten is het punt A het punt met de kleinste positieve x-coördinaat. Door A gaat een stijgende lijn l die een hoek van 75° met de x-as maakt. Punt B is het snijpunt van lijn l met de y-as. Zie figuur 2.
figuur 2: de grafiek van f en de lijn l door A en B$$, 'inline'),
  ('c3480d35-537a-445f-82ff-530a2d452cc8', '1f27c094-3af5-4b47-a0d5-9636760ec1cd', $$g sinusoïde: periode drie keer zo klein als die van f, amplitude vier keer zo klein, laagste punt in het snijpunt van f met de y-as; figuur 3; g(x) = d + a · cos(bx)$$,
   $$wiskunde-b-havo-2019-ii-sinusoide-en-lijn-context3.png$$,
   $$We bekijken nu de functie g. Deze heeft de volgende eigenschappen:
– De grafiek van g is een sinusoïde.
– De periode van de grafiek van g is drie keer zo klein is als de periode van de grafiek van f.
– De amplitude van de grafiek van g is vier keer zo klein als de amplitude van de grafiek van f.
– Een laagste punt van de grafiek van g valt samen met het snijpunt van de grafiek van f met de y-as. Zie figuur 3.
figuur 3: de grafieken van f en g
Functie g heeft een functievoorschrift van de volgende vorm:
g(x) = d + a · cos(bx)
Hierin zijn a, b en d getallen.$$, 'inline'),
  ('3c6c2142-a946-4fd2-b3c1-b0be1bd217a3', '1177746c-9452-4cfe-8678-12377e46c9fb', $$Viaduc de Garabit, spoorbrug over de Truyère; foto$$,
   $$wiskunde-b-havo-2019-ii-viaduc-de-garabit-context1.png$$,
   $$Het Viaduc de Garabit is een spoorbrug die tussen 1880 en 1884 over de rivier de Truyère in Frankrijk is gebouwd. Zie de foto.
foto: het Viaduc de Garabit$$, 'inline'),
  ('840ed027-df9e-455e-af72-9c374299654d', '1177746c-9452-4cfe-8678-12377e46c9fb', $$onderste boog benaderd door parabool y = ax² + bx; begin in oorsprong, afstand begin- en eindpunt 165,00 m, top 51,858 m boven de x-as; figuur$$,
   $$wiskunde-b-havo-2019-ii-viaduc-de-garabit-context2.png$$,
   $$De onderste boog is bij benadering een deel van een parabool.
We plaatsen de parabool in een assenstelsel, zodanig dat het beginpunt van de boog zich in de oorsprong bevindt. Zie de figuur.
Verder is de afstand tussen beginpunt en eindpunt van de boog 165,00 m en bevindt de top van de onderste boog zich 51,858 m boven de x-as.
figuur: de boog van het viaduct in een assenstelsel met breedte 165,00 en hoogte 51,858
De parabool is te beschrijven met een formule van de vorm y = ax² + bx.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('64cf567e-e1f4-4ccc-b102-990f835018fe', 'b53e4a85-5a16-4d3f-b4b9-7ddbecaca244', 1,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}]'::jsonb,
